static void xn_arr_i_deinit(void *p) {
    xn_arr_i *a = (xn_arr_i *)p;
    if (a->data != NULL) {
        free(a->data);
        a->data = NULL;
    }
    a->len = 0;
    a->cap = 0;
}

static const rt_type RT_TYPE_xn_arr_i = { "List", sizeof(xn_arr_i), xn_arr_i_deinit, NULL };

static xn_arr_i *xn_arr_i_new(size_t cap) {
    xn_arr_i *a = (xn_arr_i *)xn_gc_new(&RT_TYPE_xn_arr_i);
    memset((char *)a + sizeof(rt_header), 0, sizeof(xn_arr_i) - sizeof(rt_header));
    a->cap = cap ? cap : 4;
    a->data = malloc(sizeof(int64_t) * a->cap);
    if (a->data == NULL) { abort(); }
    return a;
}

static void xn_arr_i_push(xn_arr_i *a, int64_t v) {
    if (a->len == a->cap) {
        a->cap *= 2;
        a->data = realloc(a->data, sizeof(int64_t) * a->cap);
        if (a->data == NULL) { abort(); }
    }
    a->data[a->len++] = v;
}

static int64_t xn_arr_i_get(const xn_arr_i *a, int64_t i) {
    if (i < 0 || (size_t)i >= a->len) { xn_fatal_oob(); }
    return a->data[i];
}

static void xn_arr_i_set(xn_arr_i *a, int64_t i, int64_t v) {
    if (i < 0 || (size_t)i >= a->len) { xn_fatal_oob(); }
    a->data[i] = v;
}

static int64_t xn_arr_i_remove(xn_arr_i *a, int64_t i) {
    if (i < 0 || (size_t)i >= a->len) { xn_fatal_oob(); }
    int64_t old = a->data[i];
    for (size_t j = (size_t)i; j + 1 < a->len; j++) {
        a->data[j] = a->data[j + 1];
    }
    a->len--;
    return old;
}

static void xn_arr_i_insert(xn_arr_i *a, int64_t i, int64_t v) {
    if (i < 0 || (size_t)i > a->len) { xn_fatal_oob(); }
    if (a->len == a->cap) {
        a->cap *= 2;
        a->data = realloc(a->data, sizeof(int64_t) * a->cap);
        if (a->data == NULL) { abort(); }
    }
    for (size_t j = a->len; j > (size_t)i; j--) {
        a->data[j] = a->data[j - 1];
    }
    a->data[i] = v;
    a->len++;
}

static void xn_arr_i_clear(xn_arr_i *a) {
    a->len = 0;
}

static rt_string *xn_arr_i_join(xn_arr_i *a, rt_string *sep) {
    rt_string *res = rt_string_from_c("");
    for (size_t i = 0; i < a->len; i++) {
        if (i > 0) {
            res = xn_concat(res, rt_string_new(sep->bytes, sep->len));
        }
        res = xn_concat(res, xn_str_int(a->data[i]));
    }
    return res;
}

static void xn_arr_s_scan(void *p, void (*visit)(void *)) {
    xn_arr_s *a = (xn_arr_s *)p;
    if (a->data == NULL) { return; }
    for (size_t i = 0; i < a->len; i++) { visit(a->data[i]); }
}

static void xn_arr_s_deinit(void *p) {
    xn_arr_s *a = (xn_arr_s *)p;
    if (a->data != NULL) {
        free(a->data);
        a->data = NULL;
    }
    a->len = 0;
    a->cap = 0;
}

static const rt_type RT_TYPE_xn_arr_s = { "List", sizeof(xn_arr_s), xn_arr_s_deinit, xn_arr_s_scan };

static xn_arr_s *xn_arr_s_new(size_t cap) {
    xn_arr_s *a = (xn_arr_s *)xn_gc_new(&RT_TYPE_xn_arr_s);
    memset((char *)a + sizeof(rt_header), 0, sizeof(xn_arr_s) - sizeof(rt_header));
    a->cap = cap ? cap : 4;
    a->data = malloc(sizeof(rt_string *) * a->cap);
    if (a->data == NULL) { abort(); }
    return a;
}

